// Package resume allows interrupted runs to be resumed.
//
// When a run is canceled, the distribution directory may already contain
// part of the binaries, archives, and metadata produced for the current
// version. On the next run for the very same version, the artifacts that
// still match the current configuration are adopted, so the producing
// pipes can skip them; artifacts belonging to targets or configurations
// that no longer exist are removed, while files not generated by the
// tool are left untouched.
//
// State is persisted to artifacts.json (the artifact manifest) and to
// metadata.json (which carries the version the artifacts belong to).
package resume

import (
	"encoding/json"
	"errors"
	"io/fs"
	"os"
	"path/filepath"
	"slices"
	"strings"
	"sync"

	"github.com/caarlos0/log"
	"github.com/goreleaser/goreleaser/v2/internal/artifact"
	"github.com/goreleaser/goreleaser/v2/internal/gio"
	"github.com/goreleaser/goreleaser/v2/pkg/config"
	"github.com/goreleaser/goreleaser/v2/pkg/context"
)

// State file names, relative to the distribution directory.
const (
	MetadataFile  = "metadata.json"
	ArtifactsFile = "artifacts.json"
)

// writeLock serializes manifest writes, which may happen concurrently
// (e.g. once per build target).
var writeLock sync.Mutex

// priorMetadata is the subset of metadata.json used to decide whether a
// distribution directory can be resumed.
type priorMetadata struct {
	ProjectName string `json:"project_name"`
	Version     string `json:"version"`
}

// Detect inspects the distribution directory and, when it contains a
// previous run for the same version, enables resume mode on the context:
// previously generated artifacts that still match the configuration are
// adopted, obsolete tool-owned files are removed, and all other files are
// preserved.
//
// It returns engaged=true when resume mode was enabled. A false result
// with no error means the caller must behave as it always did (either the
// directory is absent/empty or its provenance cannot be trusted).
func Detect(ctx *context.Context) (engaged bool, err error) {
	if ctx.Config.Dist == "" {
		ctx.Config.Dist = "dist"
	}

	// single-target/partial builds intentionally only build a subset of
	// the configured targets, so the usual resume reconciliation does not
	// apply; keep their existing behavior.
	if ctx.Partial {
		return false, nil
	}

	entries, err := os.ReadDir(ctx.Config.Dist)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return false, nil
		}
		return false, err
	}
	if len(entries) == 0 {
		return false, nil
	}

	meta, err := readMetadata(ctx.Config.Dist)
	if err != nil {
		log.WithError(err).Debug("dist is not resumable")
		return false, nil
	}
	if meta.Version == "" || meta.Version != ctx.Version {
		log.WithField("previous", meta.Version).
			WithField("current", ctx.Version).
			Debug("dist is from a different version, not resuming")
		return false, nil
	}

	ctx.Resume = true
	ctx.ResumeClaimed = &sync.Map{}
	log.WithField("dist", ctx.Config.Dist).
		WithField("version", meta.Version).
		Info("resuming previous run")

	prior, err := ReadArtifacts(ctx.Config.Dist)
	if err != nil {
		log.WithError(err).Warn("could not read previous artifacts metadata, rebuilding missing items")
		prior = nil
	}

	ctx.ResumeOwned = ownedPaths(ctx.Config.Dist, prior)
	if err := reconcile(ctx, prior); err != nil {
		return true, err
	}
	if err := pruneEmptyDirs(ctx.Config.Dist); err != nil {
		return true, err
	}
	return true, nil
}

// adoptableTypes are the artifact types that can be adopted from a
// previous run. Everything else recorded as tool-owned is removed so the
// corresponding pipes run against the same state as a fresh build.
func adoptable(t artifact.Type) bool {
	switch t {
	case artifact.Binary,
		artifact.UniversalBinary,
		artifact.Header,
		artifact.CArchive,
		artifact.CShared,
		artifact.PyWheel,
		artifact.PySdist,
		artifact.UploadableArchive,
		artifact.UploadableBinary:
		return true
	default:
		return false
	}
}

// reconcile adopts artifacts that are still desired and deletes the
// tool-owned files that are not, either because their type is produced by
// a pipe which always runs (e.g. checksums) or because their target was
// removed from the configuration.
func reconcile(ctx *context.Context, prior []*artifact.Artifact) error {
	builds := make(map[string]config.Build, len(ctx.Config.Builds))
	for _, b := range ctx.Config.Builds {
		builds[b.ID] = b
	}
	archives := make(map[string]struct{}, len(ctx.Config.Archives))
	for _, a := range ctx.Config.Archives {
		archives[a.ID] = struct{}{}
	}

	var stale []string
	for _, a := range prior {
		path, ok := withinDist(ctx.Config.Dist, a.Path)
		if !ok {
			continue
		}

		// Metadata files (metadata.json) and non-file artifacts (e.g.
		// published container images) are neither adopted nor removed
		// here. The metadata pipes rewrite them on every run.
		if a.Type == artifact.Metadata {
			continue
		}

		info, err := os.Stat(path)
		if err != nil || info.IsDir() {
			// The artifact is gone, its record is simply dropped and the
			// producing pipe will rebuild it.
			continue
		}

		if !adoptable(a.Type) || !stillDesired(a, builds, archives) {
			stale = append(stale, path)
			continue
		}

		if a.Extra == nil {
			a.Extra = artifact.Extras{}
		}
		a.Extra[artifact.ExtraAdopted] = true
		ctx.Artifacts.Add(a)
		log.WithField("name", a.Name).
			WithField("type", a.Type).
			Info("reusing existing artifact")
	}

	for _, path := range stale {
		log.WithField("path", path).Info("removing stale artifact")
		if err := os.Remove(path); err != nil && !errors.Is(err, fs.ErrNotExist) {
			return err
		}
	}
	return nil
}

// stillDesired reports whether an adopted artifact still corresponds to
// something the current configuration produces.
func stillDesired(a *artifact.Artifact, builds map[string]config.Build, archives map[string]struct{}) bool {
	switch a.Type {
	case artifact.UploadableArchive, artifact.UploadableBinary:
		_, ok := archives[a.ID()]
		return ok
	default:
		return desiredBuild(a, builds)
	}
}

func desiredBuild(a *artifact.Artifact, builds map[string]config.Build) bool {
	if b, ok := builds[a.ID()]; ok {
		return a.Target == "" || slices.Contains(b.Targets, a.Target)
	}

	// Multi-main builds register each binary using its package name as
	// the ID. The unique build directory still carries the build ID, so
	// use it as a fallback.
	if id := buildIDFromPath(a.Path); id != "" {
		if b, ok := builds[id]; ok {
			return a.Target == "" || slices.Contains(b.Targets, a.Target)
		}
	}

	// Without a unique directory there is nothing tying the artifact to a
	// specific build; accept it as long as some build still targets it.
	if a.Target != "" {
		for _, b := range builds {
			if slices.Contains(b.Targets, a.Target) {
				return true
			}
		}
	}
	return false
}

// buildIDFromPath extracts the build ID from the "<id>_<target>" unique
// build directory, if the artifact is stored in one.
func buildIDFromPath(path string) string {
	dir := filepath.Base(filepath.Dir(filepath.FromSlash(path)))
	idx := strings.LastIndex(dir, "_")
	if idx <= 0 {
		return ""
	}
	return dir[:idx]
}

// Claim marks an adopted artifact as reaffirmed by the pipe that owns it,
// meaning it is still part of the expected result. It is a no-op for
// artifacts produced by the current run and safe to call concurrently.
func Claim(ctx *context.Context, a *artifact.Artifact) {
	if a != nil && ctx.ResumeClaimed != nil {
		ctx.ResumeClaimed.Store(a, struct{}{})
	}
}

// Adopted reports whether the artifact was adopted from a previous run
// and has not been claimed yet.
func Adopted(ctx *context.Context, a *artifact.Artifact) bool {
	if !artifact.ExtraOr(*a, artifact.ExtraAdopted, false) {
		return false
	}
	if ctx.ResumeClaimed == nil {
		// no claim registry in use: nothing has been claimed
		return true
	}
	_, claimed := ctx.ResumeClaimed.Load(a)
	return !claimed
}

// Finalize reconciles the directory against the final artifact list:
// adopted artifacts that no pipe reaffirmed (e.g. archives for platforms
// no longer built) and files owned by the previous run that are no longer
// produced are removed. It must run before the final artifacts.json is
// written.
func Finalize(ctx *context.Context) error {
	if !ctx.Resume {
		return nil
	}

	// Drop adopted records no pipe claimed.
	for _, a := range ctx.Artifacts.Snapshot() {
		if Adopted(ctx, a) {
			target := a
			if err := ctx.Artifacts.Remove(func(b *artifact.Artifact) bool {
				return b == target
			}); err != nil {
				return err
			}
		}
	}

	wanted := map[string]struct{}{}
	for _, a := range ctx.Artifacts.Snapshot() {
		if path, ok := withinDist(ctx.Config.Dist, a.Path); ok {
			wanted[path] = struct{}{}
		}
	}

	for _, path := range ctx.ResumeOwned {
		if filepath.Base(path) == ArtifactsFile {
			continue
		}
		if _, ok := wanted[path]; ok {
			continue
		}
		if err := os.Remove(path); err != nil && !errors.Is(err, fs.ErrNotExist) {
			return err
		}
		log.WithField("path", path).Info("removed artifact no longer produced")
	}

	return pruneEmptyDirs(ctx.Config.Dist)
}

// Checkpoint persists the current artifact list so an interruption from
// this point on can resume from everything completed so far. It is a
// no-op for fresh runs.
func Checkpoint(ctx *context.Context) error {
	if !ctx.Resume {
		return nil
	}
	return WriteArtifacts(ctx)
}

// WriteArtifacts writes the artifacts.json manifest into the distribution
// directory. It never mutates the live artifacts, so it is safe to call
// while other goroutines keep producing artifacts.
func WriteArtifacts(ctx *context.Context) error {
	items := ctx.Artifacts.Snapshot()
	out := make([]*artifact.Artifact, len(items))
	for i, a := range items {
		cp := *a
		cp.TypeS = cp.Type.String()
		cp.Path = filepath.ToSlash(filepath.Clean(cp.Path))
		out[i] = &cp
	}
	return writeJSON(ctx, out, ArtifactsFile)
}

// ReadArtifacts reads a previously written artifact manifest.
func ReadArtifacts(dist string) ([]*artifact.Artifact, error) {
	path := filepath.Join(dist, ArtifactsFile)
	bts, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var list []*artifact.Artifact
	if err := json.Unmarshal(bts, &list); err != nil {
		return nil, err
	}
	return list, nil
}

func readMetadata(dist string) (*priorMetadata, error) {
	bts, err := os.ReadFile(filepath.Join(dist, MetadataFile))
	if err != nil {
		return nil, err
	}
	var meta priorMetadata
	if err := json.Unmarshal(bts, &meta); err != nil {
		return nil, err
	}
	return &meta, nil
}

// ownedPaths resolves the file-backed artifact paths from a manifest to
// absolute paths, keeping only files within the distribution directory.
func ownedPaths(dist string, arts []*artifact.Artifact) []string {
	var out []string
	for _, a := range arts {
		if a.Type == artifact.Metadata {
			// metadata.json is rewritten on every run; artifacts.json is
			// not represented in the list and is always rewritten.
			continue
		}
		if path, ok := withinDist(dist, a.Path); ok {
			out = append(out, path)
		}
	}
	return out
}

// withinDist resolves path and reports whether it points at a regular
// location inside the distribution directory. Paths outside of dist are
// never managed by resume.
func withinDist(dist, path string) (string, bool) {
	if path == "" {
		return "", false
	}
	abs, err := filepath.Abs(filepath.FromSlash(path))
	if err != nil {
		return "", false
	}
	dabs, err := filepath.Abs(dist)
	if err != nil {
		return "", false
	}
	rel, err := filepath.Rel(dabs, abs)
	if err != nil || rel == "." || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return "", false
	}
	return abs, true
}

// pruneEmptyDirs removes empty directories below dist, never removing
// dist itself. Manually placed files prevent their directories from being
// pruned.
func pruneEmptyDirs(dist string) error {
	dabs, err := filepath.Abs(dist)
	if err != nil {
		return err
	}
	var dirs []string
	_ = filepath.WalkDir(dabs, func(path string, d fs.DirEntry, err error) error {
		if err == nil && d.IsDir() && path != dabs {
			dirs = append(dirs, path)
		}
		return nil
	})
	// deepest first
	slices.SortFunc(dirs, func(a, b string) int {
		return len(b) - len(a)
	})
	for _, dir := range dirs {
		// non-empty directories (e.g. those holding a manually placed
		// file) and ones already removed are left alone.
		_ = os.Remove(dir)
	}
	return nil
}

func writeJSON(ctx *context.Context, v any, name string) error {
	bts, err := json.Marshal(v)
	if err != nil {
		return err
	}

	writeLock.Lock()
	defer writeLock.Unlock()

	path := filepath.Join(ctx.Config.Dist, name)
	log.WithField("path", path).Debug("writing")

	tmp := path + ".tmp"
	if err := os.WriteFile(tmp, bts, 0o644); err != nil { //nolint:gosec
		return err
	}
	if err := os.Rename(tmp, path); err != nil {
		return err
	}
	return gio.Chtimes(path, ctx.Config.Metadata.ModTimestamp)
}
